"""Correctness probe only. Instruction strings are generated by Lean's PPC printer."""
import json
from pathlib import Path
import platform
import subprocess
import tempfile

root = Path(__file__).parent
probe = json.loads((root / 'power8_instruction_probe.json').read_text())
assert platform.machine() == 'ppc64le', platform.machine()
print('Native architecture:', platform.machine(), flush=True)
for line in Path('/proc/cpuinfo').read_text().splitlines()[:40]:
    if line.startswith(('cpu', 'clock', 'revision')):
        print(line, flush=True)
print('Model file SHA256:', json.dumps(probe['model_sha256']), flush=True)
subprocess.run(['cc', '--version'], check=True)

with tempfile.TemporaryDirectory() as tmp:
    tmp = Path(tmp)
    assembly = ['.text', '.abiversion 2']
    for i, case in enumerate(probe['cases']):
        name = f'probe_{i}'
        assembly += [f'.globl {name}', f'.type {name}, @function', f'{name}:']
        assembly += probe['setup'] + case + probe['store'] + probe['return']
    (tmp / 'probe.s').write_text('\n'.join(assembly) + '\n')
    n = len(probe['cases'])
    c = '#include <stdio.h>\n#include <stdint.h>\n'
    c += '\n'.join(f'extern void probe_{i}(const uint64_t *, uint64_t *);' for i in range(n))
    c += '\ntypedef void (*fn)(const uint64_t *, uint64_t *);\nint main(void) {\n'
    c += 'fn fs[]={' + ','.join(f'probe_{i}' for i in range(n)) + '};\n'
    c += '''uint64_t a[6]; unsigned trial=0;
while(fread(a,sizeof(a),1,stdin)==1){
for(unsigned i=0;i<sizeof(fs)/sizeof(fs[0]);i++){
uint64_t b[2]={0}; fs[i](a,b);
printf("%u %u %016llx%016llx\\n",trial,i,(unsigned long long)b[0],(unsigned long long)b[1]);
}trial++;}return 0;}
'''
    (tmp / 'probe.c').write_text(c)
    subprocess.run(['cc', '-O2', '-mcpu=power8', str(tmp / 'probe.c'), str(tmp / 'probe.s'), '-o', str(tmp / 'probe')], check=True)
    corpus = b''.join(bytes.fromhex(t['input']) for t in probe['trials'])
    result = subprocess.run([str(tmp / 'probe')], input=corpus, stdout=subprocess.PIPE, check=True)
    lines = result.stdout.decode().splitlines()
    assert len(lines) == n * len(probe['trials']), len(lines)
    for index, line in enumerate(lines):
        trial, case, value = line.split()
        trial, case = int(trial), int(case)
        assert (trial, case) == divmod(index, n)
        mask = int(probe['masks'][case], 16)
        expected = int(probe['trials'][trial]['expected'][case], 16)
        assert int(value, 16) & mask == expected & mask, (trial, case, value, hex(expected))
    print(f'PASS: {len(lines)} native instruction/input pairs matched the model; undefined MT VSR low halves were masked.', flush=True)
